sourcesContent:
import { useState } from 'react';
import {
  FiActivity, FiArrowRight, FiBarChart2, FiBell, FiBookOpen, FiBox,
  FiCheck, FiChevronDown, FiCloud, FiCode, FiGrid, FiHeart, FiHome,
  FiLayers, FiMail, FiMapPin, FiMenu, FiMonitor, FiPackage, FiPhone,
  FiPlus, FiSearch, FiSettings, FiShoppingCart, FiSmartphone, FiTrendingUp,
  FiUsers, FiX
} from 'react-icons/fi';
import logo from './assets/logo.png';

const navItems = ['Home', 'Solutions', 'Industries', 'Products', 'Technology', 'Company'];
const solutions = [
  [FiLayers, 'Hospital ERP', 'Complete hospital management with OPD, IPD, Pharmacy, Lab, Billing & more.', 'blue'],
  [FiActivity, 'Pharmacy ERP', 'Manage inventory, sales, purchases, GST, expiry and more.', 'mint'],
  [FiBookOpen, 'Pathology Software', 'Lab management, test reports, QR reports, sample tracking and analytics.', 'violet'],
  [FiBox, 'School ERP', 'Students, fees, attendance, exams, transport and communication.', 'sky'],
  [FiHome, 'College ERP', 'Admission, departments, examination, fees, library and more.', 'orange'],
  [FiMonitor, 'Website Development', 'Corporate, eCommerce, dynamic & custom web solutions.', 'blue'],
  [FiSmartphone, 'Mobile App Development', 'Android, iOS & cross-platform apps that deliver exceptional experiences.', 'teal'],
  [FiCloud, 'Cloud Solutions', 'Cloud hosting, backup, scalability and security for your business.', 'blue'],
  [FiUsers, 'CRM Solutions', 'Leads, deals, tasks and customer management in one place.', 'violet'],
  [FiSettings, 'AI & Automation', 'AI chatbots, workflow automation, document processing & more.', 'blue'],
  [FiShoppingCart, 'E-Commerce Solutions', 'Powerful eCommerce platforms with payment gateway.', 'violet'],
  [FiPackage, 'Custom Software', 'Tailor-made software built as per your unique business needs.', 'blue']
];
const industries = [[FiHeart, 'Healthcare'], [FiActivity, 'Pharmacy'], [FiBookOpen, 'Education'], [FiMonitor, 'Corporate'], [FiHome, 'Real Estate'], [FiShoppingCart, 'Retail'], [FiBox, 'Logistics'], [FiBarChart2, 'Manufacturing']];
const technologies = [['React', '⚛'], ['Next.js', 'N'], ['Node.js', '⬡'], ['Python', '⌘'], ['PHP', 'php'], ['Java', '♨'], ['Laravel', '⌁'], ['MySQL', '◫'], ['MongoDB', '◉'], ['AWS', 'aws'], ['Azure', '◈'], ['Firebase', '♨'], ['Docker', '▣']];
const stories = [
  ['Hospital Management System', 'Complete solution for 100-bed multi-speciality hospital.', 'hospital'],
  ['Pharmacy ERP', 'Automated inventory & sales for retail pharmacy chain.', 'pharmacy'],
  ['Pathology Management System', 'Digital lab management & reporting system.', 'pathology'],
  ['School Management System', 'Smart school ERP for 500+ students.', 'school'],
  ['E-Commerce Platform', 'Full-stack e-commerce solution with payment gateway.', 'ecommerce']
];
const faqs = ['What services does Arnex Tech provide?', 'How long does a project typically take?', 'Do you provide custom solutions?', 'Are your solutions scalable?', 'Do you provide after-sales support?'];

const scrollTo = (id) => document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' });

function Brand() {
  return <a className="brand" href="#home" onClick={(event) => { event.preventDefault(); scrollTo('home'); }}><img src={logo} alt="Arnex Tech" /></a>;
}

function Button({ children, ghost, onClick, type = 'button' }) {
  return <button type={type} className={`button${ghost ? ' button--ghost' : ''}`} onClick={onClick}>{children}<FiArrowRight /></button>;
}

function Proof({ icon: Icon, value, text, inverse }) {
  return <div className={`proof${inverse ? ' proof--inverse' : ''}`}><span><Icon /></span><div><b>{value}</b><small>{text}</small></div></div>;
}

function Metric({ label, value, growth }) {
  return <div className="metric"><small>{label}</small><b>{value}</b><span>↗ {growth}<em>vs last month</em></span></div>;
}

function Dashboard() {
  const sideIcons = [FiGrid, FiHome, FiBox, FiUsers, FiSettings];
  return <div className="dashboard-wrap" aria-label="Business analytics dashboard preview">
    <div className="dashboard">
      <aside className="dash-sidebar"><div className="dash-avatar">A</div>{sideIcons.map((Icon, index) => <span className={`dash-nav${index === 0 ? ' active' : ''}`} key={index}><Icon /></span>)}</aside>
      <div className="dash-main">
        <div className="dash-topbar"><div><b>Arnex Business Intelligence</b><small>Business overview</small></div><div className="dash-actions"><FiSearch /><span className="notification"><FiBell /><i /></span><span className="profile-dot">S</span></div></div>
        <div className="metrics"><Metric label="Total Revenue" value="₹24.8L" growth="24.4%"/><Metric label="Total Customers" value="2,486" growth="18.6%"/><Metric label="Total Orders" value="8,921" growth="32.4%"/><div className="metric metric--chart"><small>Top Channels</small><div className="donut"><span /></div><div className="legend"><b>Web <em>40%</em></b><b>Mobile <em>28%</em></b><b>Partner <em>20%</em></b></div></div></div>
        <div className="dash-lower"><div className="chart-card"><div className="chart-heading"><b>Sales Overview</b><small>This Year⌄</small></div><div className="line-chart"><span className="chart-grid g1"/><span className="chart-grid g2"/><span className="chart-grid g3"/><svg viewBox="0 0 430 150" preserveAspectRatio="none"><defs><linearGradient id="chartArea" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#1c63ee" stopOpacity=".24"/><stop offset="1" stopColor="#1c63ee" stopOpacity="0"/></linearGradient></defs><path d="M0 125 L32 113 L67 100 L97 77 L128 91 L163 61 L198 82 L231 55 L263 72 L299 37 L332 50 L365 20 L400 33 L430 5 L430 150 L0 150Z" fill="url(#chartArea)"/><polyline points="0,125 32,113 67,100 97,77 128,91 163,61 198,82 231,55 263,72 299,37 332,50 365,20 400,33 430,5" fill="none" stroke="#2464e9" strokeWidth="3"/></svg></div><div className="months"><span>Jan</span><span>Feb</span><span>Mar</span><span>Apr</span><span>May</span><span>Jun</span><span>Jul</span></div></div><div className="orders"><div className="chart-heading"><b>Recent Orders</b><small>View all</small></div>{['#ORD1248', '#ORD1247', '#ORD1246', '#ORD1245'].map((order, index) => <div className="order" key={order}><span className="order-icon"><FiBox /></span><b>{order}</b><em className={index === 3 ? 'cancelled' : ''}>{['₹21,540', '₹18,760', '₹12,300', '₹9,890'][index]}<small>{index === 3 ? 'Cancelled' : 'Completed'}</small></em></div>)}</div></div>
      </div>
    </div>
    <div className="growth-card"><FiTrendingUp /><b>+28.4%</b><span>Sales growth</span><div className="bars"><i/><i/><i/><i/></div></div>
  </div>;
}

function SectionHeading({ overline, subtitle, action }) {
  return <div className="section-heading"><div><span className="overline">{overline}</span>{subtitle && <p>{subtitle}</p>}</div>{action && <button className="text-action">View All {overline}<FiArrowRight /></button>}</div>;
}

function SolutionCard({ item }) {
  const [Icon, title, text, tone] = item;
  return <article className="solution-card"><div className={`solution-icon ${tone}`}><Icon /></div><div><h3>{title}</h3><p>{text}</p></div><button>Learn More <FiArrowRight /></button></article>;
}

function FooterLinks({ title, links }) {
  return <div className="footer-links"><h3>{title}</h3>{links.map((link) => <a href="#home" key={link}>{link}</a>)}</div>;
}

